# Glossary of named things across the CIDM 6333 decks.
# Fields: term, cat, aliases (also matched when auto-linking), what, when (who/when), why (why it is in the course),
# src (where to read more), ch (textbook chapters). Course vocabulary follows Appendix D of the Course Topic Guide and the decks.
# Categories: course · harness · protocol · system · paper · bench · method · org

E = []
def g(term, cat, what, when="", why="", src="", aliases=(), ch=()):
    E.append(dict(term=term, cat=cat, what=what, when=when, why=why, src=src, aliases=list(aliases), ch=list(ch)))

# ---------------- course vocabulary ----------------
g("Evolution", "course", "The unit of progression: one lecture, one build, one sortie, each adding one layer to the system. E0 is orientation; E1 through E12 add the loop, patterns, tools, MCP, the harness, context, memory, coordination, failure, evaluation, observability, and deployment, in that order. Evolutions compress or expand to fit the time available; the order is what matters.", "", "Every deck, exercise, and flight card is filed by Evolution.", "Course Topic Guide, Using this book", aliases=("Evolutions", "E0", "E1", "E2", "E3", "E4", "E5", "E6", "E7", "E8", "E9", "E10", "E11", "E12"), ch=(22,))
g("Sprint and Drift", "course", "The method. Sprint: produce the work with AI, and log what the AI did. Drift: defend the work without AI, to a reader who can ask why. The names come from naval practice: a ship cannot move and listen at once.", "Developed for CIDM 6330 (Software Architecture) and carried into CIDM 6333.", "The AI log and the Drift are how understanding is checked, rather than artifacts.", "Course Topic Guide, Chapter 22; sprintanddrift.substack.com", aliases=("Sprint", "Drift", "The Sprint", "Drifts"), ch=(22,))
g("Sortie", "course", "One flight of one flight card in one sitting: you run the build against its pre-registered claim and record what came back. Sortie 7 flies Flight Card 7, and so on.", "Vocabulary borrowed from aircraft flight test.", "The sortie is the unit of evidence; a claim without a sortie is an opinion.", "Course Topic Guide, Chapter 23", aliases=("Sorties", "Sortie 1", "Sortie 7", "Sortie 8", "Sortie 9", "Sortie 10", "Sortie 11"), ch=(23,))
g("Flight card", "course", "The pre-registered plan for a sortie: the design claim, the envelope (center, corner, or expansion), systems under test, substrate, test points, instrumentation, entry conditions, and the falsifiers, all written before the run. The flight log records what happened.", "Appendix A of the Course Topic Guide is the template.", "Pre-registration is what makes a passing run evidence instead of a story told afterwards.", "Course Topic Guide, Chapter 23 and Appendix A", aliases=("Flight Card", "flight cards", "Flight Card 1", "Flight Card 7", "Flight Card 8", "Flight Card 10", "FC2", "FC3", "flight log", "Flight log", "ENVELOPE", "TEST POINTS", "INSTRUMENTATION", "ENTRY CONDITIONS", "SYSTEMS UNDER TEST", "SUBSTRATE", "PRE-REGISTERED FALSIFIERS", "DESIGN CLAIM"), ch=(23,))
g("Falsifier", "course", "A pre-registered observation that would prove a design claim false. A flight card lists them before the sortie; the verdict after the sortie is REFUTED or NOT-REFUTED, never 'it worked'.", "From Popper's falsificationism, applied to engineering claims.", "The course scores claims by what would have refuted them, not by whether the demo ran.", "Course Topic Guide, Chapter 23", aliases=("Falsifiers", "falsifiers", "REFUTED", "NOT-REFUTED"), ch=(23,))
g("Chase", "course", "The independent observer of a sortie: a classmate who writes the verdict from the evidence alone (ledger, receipts, test output), never from the pilot's account. In flight test the chase plane watches the test aircraft from outside.", "", "Every sortie has a Chase; the Go/No-Go before a sortie and the review after it are the Chase's, in writing, in the repository.", "Course Topic Guide, Chapter 23", aliases=("The Chase", "Your Chase", "CHASE", "Chase review"), ch=(23,))
g("Go / No-Go", "course", "The Chase's decision that a sortie may fly (the entry conditions are met) or may not, recorded in the repository before the sortie.", "", "A sortie flown without a Go is unplanned, and its result is not evidence.", "Course Topic Guide, Chapter 23", aliases=("No-Go", "NO-GO", "Go/No-Go"), ch=(23,))
g("Squawk", "course", "An anomaly recorded at debrief and routed somewhere: an issue, a feedback entry, an amendment to the card, or a re-fly. In aviation a squawk is a maintenance write-up.", "", "The debrief is where findings become work items instead of memories.", "Course Topic Guide, Appendix D", aliases=("squawks",), ch=(23,))
g("Design Analysis", "course", "The course's dissection of a system: the nine components (perception, reasoning, planning, action, memory, tools, coordination, evaluation, governance) each named with its mechanism, and one 'why' paragraph that states the problem the design answered and what it cost.", "Appendix B of the Course Topic Guide is the template; one is done live in most lectures.", "The survey half of the course asks the same question of every system: why was it designed this way?", "Course Topic Guide, Chapter 24 and Appendix B", aliases=("Design Analyses", "Live Design Analysis", "Design Analysis Ledger", "nine components"), ch=(24, 2))
g("Teardown", "course", "A lecture segment that takes one real system apart with the Design Analysis: FIPA and BDI, CAMEL and MetaGPT, the LangGraph supervisor, Claude Code subagents, and so on. Each ends with the mechanism, the design choice, the cost, and the failure mode.", "", "Teardowns are the survey thread of each Evolution.", "Course Topic Guide, Chapter 24", aliases=("Teardowns",), ch=(24,))
g("Final System", "course", "The end-of-course build: the harness assembled across the Evolutions, used to build an MVP tied to the E0 pitch, with V&V that assures the harness's actions, validated by a real user at the closeout.", "", "", "Course Topic Guide, Chapter 26; the Final System handout", aliases=("The Final System", "closeout", "closeout ceremony", "Closeout"), ch=(26,))
g("Index zero", "course", "The human's position in the system: first in priority (your intent drives every decision) and final in authority (you sign off, not the model). The Zero Doctrine is the answer to the Degradation Pattern.", "gzkit's term; the E0 lecture's title.", "Everything in the course's governance follows from it: gates, attestation, the Chase.", "Course Topic Guide, Chapter 3", aliases=("index zero", "Index Zero", "Zero Doctrine"), ch=(3,))
g("Degradation Pattern", "course", "The observed slide in human review as a model keeps producing acceptable output: careful reading becomes skimming, skimming becomes approving, approving becomes absence. The system still runs; nobody is answering for it. Its three names in the course: cognitive surrender (the human stops judging), mediated observation (the human sees only what the model reports), and governance theater (the gates exist on paper and nothing enforces them).", "Chapter 3; the E0 lecture.", "The course's governance apparatus exists to interrupt this slide.", "Course Topic Guide, Chapter 3", aliases=("Degradation", "cognitive surrender", "mediated observation", "governance theater"), ch=(3,))
g("Covenant", "course", "gzkit's five-clause agreement between the human and the agent about what each may do and what each must record. Governance, in the course's sense, is this agreement plus the mechanisms that enforce it.", "", "", "Course Topic Guide, Chapter 3", aliases=("covenant", "the covenant"), ch=(3,))
g("Five gates", "course", "gzkit's five checkpoints on a piece of work: Gate 1 ADR (the decision is written), Gate 2 TDD (a test exists and was red first), Gate 3 Docs, Gate 4 BDD (behavioral acceptance), Gate 5 Human attestation. The Lite lane runs gates 1–2; the Heavy lane runs all five.", "", "A model's self-review is at most Gate-4 evidence, never Gate 5 (rule GZK-GOV-007).", "Course Topic Guide, Chapter 3", aliases=("Gate", "Gates", "Gate 4", "Gate 5", "Gate-4", "Gate-5", "Lite", "Heavy", "lane", "Lane", "GZK-GOV-007"), ch=(3,))
g("Attestation", "course", "A human's recorded judgment that work is Completed, Completed — Partial, or Dropped. It is Gate 5, and it can be repudiated later if the record shows the work did not exist as attested.", "gzkit; the June 2026 repudiations are the casebook example.", "", "Course Topic Guide, Appendix D and Appendix G", aliases=("attestation", "attestations", "Attestations", "repudiation"), ch=(3, 9))
g("Ledger", "course", "The append-only event log that is the system's runtime truth: every command, verdict, gate, and attestation, dated. gzkit writes it as JSONL; the course asks your harness to keep one too.", "", "'The ledger is the black box': what anyone says about a run is a claim; the ledger is evidence.", "Course Topic Guide, Appendix D", aliases=("ledger", "ledger.jsonl", "the ledger"), ch=(3, 12))
g("Receipt", "course", "A schema-validated record of a command's observed result: the command, its exit code, its output hash, the time. A claim without a receipt is not evidence.", "gzkit", "Sortie 9's falsifier is 'a claim in the flight log with no receipt'.", "Course Topic Guide, Appendix D", aliases=("receipts", "Receipts"), ch=(18, 20))
g("Layers of truth", "course", "gzkit's three layers: L1 canon (the files in the repository: intent, ADRs, AGENTS.md), L2 ledger (what happened), L3 derived (summaries, memory, anything a model wrote about L1 or L2). Precedence: L2 beats L1 beats L3. The file beats the memory of the file.", "", "Figure 14 and the memory week apply it: a retrieved record is L3 and loses to the file it describes.", "Course Topic Guide, Appendix D", aliases=("layers of truth", "L1", "L2", "L3", "canon", "CANON", "DERIVED"), ch=(15,))
g("Brief (OBPI)", "course", "One Brief Per Item: gzkit's unit of human review, with requirements, acceptance criteria, and verification for one piece of work. Requirements are numbered (REQ-1, REQ-2) so a reviewer can cite the one a change fails.", "", "", "Course Topic Guide, Appendix D", aliases=("OBPI", "brief", "briefs", "B-07"), ch=(25,))
g("ADR", "course", "Architecture Decision Record: intent, decision, consequences, and alternatives, written before the code. The course's ADR-1 (E2) and ADR-2 (E7) are yours; gzkit's are numbered by release (ADR-0.18.0).", "Michael Nygard's 2011 template (title, context, decision, status, consequences); the course adds intent and alternatives, as in CIDM 6330. gzkit ADRs the decks cite: 0.0.2 (a standard-library CLI, argparse over click: popularity is not rationale), 0.0.9 (the state doctrine, layers of truth), 0.0.31 (the distribution invariant), 0.0.37 (AGENTS.md is rendered, not hand-edited), 0.0.54 (AGENTS.md is a map, not an encyclopedia), 0.0.71 (the first repudiated attestation), 0.0.73 (the hollow antibody), 0.0.74 (MX mode), 0.18.0 (the subagent pipeline).", "Gate 1 is 'the ADR exists'. A decision with no record cannot be defended in Drift.", "https://cognitect.com/blog/2011/11/15/documenting-architecture-decisions", aliases=("ADRs", "ADR-1", "ADR-2", "ADR-0.18.0", "ADR-0.0.71", "ADR-0.0.74", "ADR-0.0.2", "ADR-0.0.9", "ADR-0.0.31", "ADR-0.0.37", "ADR-0.0.54", "ADR-0.0.73"), ch=(25,))
g("PRD", "course", "Product Requirements Document: what the system is for and what it must do, written in E1 before the loop exists. Flight cards take their DESIGN CLAIM and falsifiers from it.", "", "", "Course Topic Guide, Chapter 25", aliases=("docs/prd.md",), ch=(25,))
g("RED witness", "course", "Proof that a test fails without the change it covers: the test is recorded red before the code makes it green. Mutation testing is the general form; gzkit records the witness with gz arb red.", "TDD's red-green discipline; DeMillo, Lipton & Sayward (1978) for mutation testing.", "E10's Sortie 10 claim is that the gate fails when it should; the RED witness is how you show it.", "Course Topic Guide, Appendix D", aliases=("RED", "red witness", "Red Witness"), ch=(19,))
g("Expansion card", "course", "A flight card at the edge of the envelope: it extends the claim beyond the center case, usually after a center-of-envelope sortie has passed. 'Center', 'corner', and 'expansion' are the three envelope settings.", "", "", "Course Topic Guide, Chapter 23", aliases=("expansion card", "Expansion", "envelope", "Corner of the envelope", "Center of the envelope"), ch=(23,))
g("Harness", "course", "The software that turns a model into an agent: the loop, the tools, the permissions, the context assembly. Claude Code, Codex, and OpenCode are vendor harnesses; the files you write to steer one are your harness (Figure 17).", "'Harness engineering' is the 2025–26 name for building this layer deliberately.", "The Final System is a harness plus proof that it can build something.", "Course Topic Guide, Chapters 8, 9, 14", aliases=("harness", "harnesses", "harness engineering", "Harness engineering", "Meta-harness", "meta-harness"), ch=(8, 14))
g("V.I.B.E.S.", "course", "Velocity Increased, Bugs Expected Software: gzkit's name for the failure class where generation speed outruns verification.", "", "", "Course Topic Guide, Appendix D", aliases=("VIBES", "V.I.B.E.S"))
g("Nine agent failure modes", "course", "gzkit's catalogue, sourced to frontier system cards: safeguard circumvention, reckless action, fabrication, skipped cheap verification, correction fails, dishonest when caught, hallucinated authorization, security shortcut, metagaming the gate. Each has a red-team probe (Appendix C).", "", "The decks cite them by number (#3 fabrication, #9 metagaming).", "Course Topic Guide, Appendix C", aliases=("Appendix C", "App. C", "failure modes", "nine modes"), ch=(20,))
g("Summary laundering", "course", "A human-side failure: a model's summary of evidence is treated as the evidence. In gzkit's May 2026 incident, summaries ten subagents deep became 'facts' nobody had checked.", "Course term; Appendix C human-side patterns.", "E9's planted-falsehood lab is this failure at the smallest scale.", "Course Topic Guide, Appendix C and Appendix G", aliases=("laundering",), ch=(18,))
g("HandoffResult", "course", "The typed claim a worker returns to the controller: status from a closed set (DONE, DONE_WITH_CONCERNS, NEEDS_CONTEXT, BLOCKED), files changed, and evidence (the test command and its exit code). Anything that does not parse is rejected; there is no default branch that returns DONE.", "gzkit ADR-0.18.0; field names are the course's.", "E8's rule one: a worker's result is a typed claim.", "E8 lecture, slide 7", aliases=("DONE", "DONE_WITH_CONCERNS", "NEEDS_CONTEXT", "BLOCKED", "dispatch record", "dispatch records"), ch=(17,))
g("ReviewResult", "course", "The typed verdict a reviewer returns: PASS, FAIL, or CONCERNS, with findings that each cite a location (file:line, test id, diff hunk) and a list of what was checked. FAIL and CONCERNS need a finding; a verdict with no citations is rejected as malformed.", "gzkit ADR-0.18.0; field names are the course's.", "E8's rule two: a verdict counts only if it cites evidence and its author could not edit.", "E8 lecture, slide 7", aliases=("PASS", "FAIL", "CONCERNS", "verdict", "ReviewResults"), ch=(17,))
g("Controller, worker, reviewer", "course", "The division of labor the course builds in E8: a controller dispatches one task, a worker (implementer) returns a HandoffResult, a reviewer that cannot edit returns a ReviewResult, and the controller merges only on PASS. Plan, do, check under every name since FIPA.", "", "", "E8 lecture; Figure 09", aliases=("controller", "worker", "reviewer", "implementer", "plan, do, check", "Plan, do, check"), ch=(17,))
g("Persona (traits, anti-traits)", "course", "A role specification you can test: one job, observable traits ('cites file and line for every finding'), anti-traits ('does not rewrite the code it reviews'), and the why (what breaks if the role fails). 'You are a world-class senior engineer' is deleted on sight.", "", "The anti-trait explains; the permission deny enforces. Both, in that order.", "E8 lecture, slide 6", aliases=("persona", "personas", "anti-traits", "anti-trait"), ch=(17,))
g("Exceptional", "course", "The tier above a strong pass on a sortie: the card's extra, harder claim (two-stage review, a calibrated judge that survives injection, the removal that turns exactly the predicted cases red).", "", "", "Course Topic Guide, Chapter 23", aliases=("Exceptional mark",))
g("Route A / Route B", "course", "The two toolkit routes. Route A: a subscription harness plus a small API budget. Route B: fully local, with Ollama and open-weight models sized to the hardware. Path A and Path B in the memory Evolution are the embedding (Ollama) and word-overlap retrievers.", "", "", "Course Topic Guide, Appendix F", aliases=("Route A", "Route B", "Path A", "Path B"))
g("Judgment loop", "course", "The closer from CIDM 6330 used at the end of chapters and teardowns: name the decision, the characteristics it privileged, the cost, the failure mode, and the preservation mechanism.", "", "", "Course Topic Guide, Conventions", aliases=("judgment loop", "preservation mechanism", "Preservation"))
g("Tree Hollow", "course", "The Sprint and Drift essay that opens the course. Its stake: a system can produce an answer without being able to answer for it.", "sprintanddrift.substack.com", "First reading of E0.", "https://sprintanddrift.substack.com")

# ---------------- gzkit ----------------
g("gzkit", "course", "The GovZero Kit: the course's reference design, a pip-installable governance toolkit with a ledger, gates, lanes, briefs, attestations, receipts, and a controller–worker pipeline. It is the one system for which the course has the entire record, including what went wrong (Appendix G, the incident casebook).", "Started January 2026; descended from GovZero, with lineage from GitHub's spec-kit and the CLAUDE.md conventions.", "Every chapter's 'Reference design' section shows what gzkit did about that week's problem.", "gzkit.org; github.com/tvproductions/gzkit", aliases=("GovZero", "gz", "gz status", "gz arb red", ".gzkit"), ch=(25,))

# ---------------- harness: vendor harnesses and their parts ----------------
g("OpenCode", "harness", "The open-source terminal coding agent the course uses as its harness: a TUI, a loop, built-in tools (read, edit, shell, webfetch), built-in agents (build, plan, general, explore, scout), permissions, skills, custom agents, commands, MCP, and plugins. AGENTS.md is its rules file.", "Launched June 2025 by Anomaly (the former SST team); MIT-licensed; any provider or model. Repository github.com/anomalyco/opencode.", "Figure 17's middle ring. Students build their harness on it.", "https://opencode.ai/docs/", aliases=("opencode", "OpenCode Go", "OpenCode Zen", "Zen", "Go", "Big Pickle", "opencode/big-pickle", "TUI", "opencode.json"), ch=(14,))
g("Claude Code", "harness", "Anthropic's agentic coding tool: a terminal harness with tools, permissions, hooks (SessionStart, UserPromptSubmit, PreToolUse, PostToolUse, PreCompact, Stop, SessionEnd, and more), subagents in .claude/agents/, skills, and CLAUDE.md as its rules file. The Claude Agent SDK exposes the same loop to programs.", "Research preview February 2025; general availability May 2025.", "The teardown subject for subagents and hooks; the hook names on the E3 and E6 slides are Claude Code's.", "https://code.claude.com/docs", aliases=("CLAUDE.md", "Claude Agent SDK", "SessionStart", "PreToolUse", "PostToolUse", "PreCompact", "UserPromptSubmit", "SessionEnd", "Claude Code subagents", "subagent", "subagents", "Subagents"), ch=(8,))
g("Codex", "harness", "OpenAI's coding agents: Codex CLI (open-source terminal agent, April 2025) and the cloud Codex agent that runs tasks in sandboxes (May 2025). AGENTS.md began as Codex's rules-file convention.", "", "A second vendor harness for comparison; its 'background agent' form is the E9–E12 survey subject.", "https://openai.com/codex/", aliases=("Codex CLI", "Codex cloud", "OpenAI Agents SDK"), ch=(8, 9))
g("Cursor", "harness", "An AI code editor (a VS Code fork) with an agent mode, rules files (.cursor/rules), and its own background agents.", "Anysphere, 2023 onward.", "One of the harnesses in the E8 and E9 feature comparisons.", "https://cursor.com", aliases=(".cursor/rules",))
g("GitHub Copilot", "harness", "GitHub's AI pair programmer, from inline completion (2021) to an agent mode (February 2025) and a cloud coding agent that works on a branch and opens pull requests (May 2025; renamed the cloud agent in April 2026).", "", "", "https://github.com/features/copilot", aliases=("Copilot",))
g("Gemini CLI", "harness", "Google's open-source terminal agent for Gemini models, released June 2025; one of the harnesses compared in the 2025 survey.", "", "", "https://github.com/google-gemini/gemini-cli")
g("AGENTS.md", "harness", "A plain Markdown file at the repository root that the harness loads into every turn: what the system is, what it must never do, the commands to run, where things live. OpenCode reads it (and CLAUDE.md as a fallback). The course caps it at 4,000 characters: a map, not an encyclopedia.", "Began as the Codex convention in 2025; agents.md documents the cross-vendor format.", "Drawer one in Figure 14; the first probe of every exercise is whether the model answers from it.", "https://agents.md; https://opencode.ai/docs/rules/", aliases=("agents.md", "rules file", "instruction file", "instruction files"), ch=(14, 15))
g("Skills", "harness", "A folder with a SKILL.md: frontmatter (name, description) plus a procedure. The harness shows the model only the name and description every turn and loads the body when the model calls the skill tool: progressive disclosure. In OpenCode they live in .opencode/skills/<name>/.", "Anthropic's Agent Skills, October 2025; OpenCode supports the same layout.", "Drawer three in Figure 14; Figure 15 follows one from disk to the turn it runs.", "https://opencode.ai/docs/skills/; Anthropic, 'Equipping agents for the real world with Agent Skills' (2025)", aliases=("skill", "SKILL.md", "Agent Skills", "skill tool", "progressive disclosure"), ch=(14,))
g("Hooks", "harness", "Code the harness runs around the loop's events: before and after a tool call, at session start, before compaction. Claude Code names them SessionStart, PreToolUse, PostToolUse, PreCompact; OpenCode's are plugin hooks such as tool.execute.before. A hook is a mechanism in the loop; a sentence in the prompt is a request.", "", "E3 calls hooks 'a membrane'; E10 puts your first gate in one.", "https://opencode.ai/docs/plugins/; Claude Code hooks reference", aliases=("hook", "plugin", "plugins", "tool.execute.before", "membrane"), ch=(12,))
g("Permissions", "harness", "The harness's gate on tool calls: allow, ask, or deny per tool and per pattern (edit, shell, webfetch, skill, task). In OpenCode they live in opencode.json and can be overridden per agent. A reviewer with edit: deny cannot fix the code it judges, whatever its prompt says.", "", "E3's point: the gate is enforced by the harness, not requested of the model.", "https://opencode.ai/docs/permissions/", aliases=("permission", "permission gate", "edit: deny", "ask on bash"), ch=(12,))
g("Compaction", "harness", "What the harness does when the context window fills: the model writes a summary of the history, and the summary replaces it. It is the middle ring's own answer to a finite window, and you did not write it and cannot review it before it happens.", "", "E6's budget record and the handoff file exist because compaction loses what the model thought mattered.", "Anthropic, 'Effective context engineering for AI agents' (2025)", aliases=("compaction", "compacted"), ch=(15,))
g("Context window", "harness", "The text the model reads on one call: system prompt, rules file, tool list, skill index, history, and whatever memory adds. It is rebuilt every turn and it has a budget; the more tokens in it, the less reliably the model attends to any one of them.", "", "E6 treats the window as an engineered artifact with a budget (Figure 07).", "Anthropic, 'Effective context engineering for AI agents' (2025)", aliases=("context", "window", "the window", "attention budget", "Context engineering", "context engineering"), ch=(15,))
g("Handoff", "harness", "A document one session writes for the next: what was done, what is open, where the truth lives. Cheap, one file, and written by the model that is about to lose its context, so it preserves what that model thought mattered.", "", "E6's build; the weakest of the memory strategies in Figure 14's table, and the most common.", "Course Topic Guide, Chapter 15", aliases=("handoff", "handoff.md", "Handoffs", "handoffs"), ch=(15,))
g("Memory layer (recall.py)", "harness", "The course's local memory: memory.jsonl (dated records with a source file and a retain_until date), a retriever that scores records against a question and injects the hits as a block marked 'data, not instructions', an evict command that removes expired records, and a ledger of every add, recall, and evict.", "Built in E7's lab.", "Figure 08 and Figure 14: memory is a claim with a date, and the loop does not open the drawer by itself.", "CIDM6333_Lab_E7_Memory handout", aliases=("recall.py", "recall", "memory.jsonl", "memory-ledger.jsonl", "retain_until", "evict", "retriever", "Retention", "retention rule"), ch=(16,))
g("Tool", "harness", "A function the model can call by name with typed arguments: a schema (the contract), a side-effect class (read, write, destructive), and a permission that gates the call. The model is an untrusted caller; the harness runs the tool and returns the result into the next window.", "Function calling arrived in the OpenAI API in June 2023; the MCP tool primitive generalized it.", "E3: tools as contracts. Figure 04 plays one call through model, harness, gate, human, tool, and ledger.", "Course Topic Guide, Chapter 12", aliases=("tools", "Tools", "tool call", "function calling", "custom tool", "custom tools", "side-effect class"), ch=(12,))

# ---------------- protocols and standards ----------------
g("MCP", "protocol", "Model Context Protocol: a client–server protocol over JSON-RPC in which a host (the harness) connects clients to servers that expose three primitives, tools, resources, and prompts, with negotiated capabilities. One server serves every client: N×M integrations become N+M.", "Released by Anthropic in November 2024; the decks follow its 2025–26 revisions (Streamable HTTP, OAuth-based authorization, stateless core) and its donation to the Linux Foundation's Agentic AI Foundation in December 2025.", "E4 builds a server; E5 covers its security and trust boundaries (Figure 05, Figure 06).", "https://modelcontextprotocol.io", aliases=("Model Context Protocol", "MCP server", "MCP servers", "GitHub MCP", "host", "hosts", "Streamable HTTP", "FastMCP", "Python SDK", "server registry", "elicitation"), ch=(13, 14))
g("JSON-RPC", "protocol", "A lightweight remote-procedure-call format in JSON (version 2.0, 2010): a request has a method, params, and an id; a response has a result or an error. MCP's messages are JSON-RPC 2.0.", "", "", "https://www.jsonrpc.org/specification", aliases=("JSON-RPC 2.0",))
g("JSON Schema", "protocol", "A vocabulary for describing the shape of JSON data: types, required fields, enums. Tool argument schemas, HandoffResult, and ReviewResult are JSON Schema in spirit; Pydantic and Zod generate it from typed code.", "", "A closed status enum in the schema is what makes a result parse fail-closed.", "https://json-schema.org", aliases=("schema", "schemas", "Pydantic", "Zod"))
g("OAuth 2.1 and PKCE", "protocol", "The authorization framework MCP's remote transport uses: a client obtains a scoped token from an authorization server, with PKCE (Proof Key for Code Exchange) binding the code to the client that requested it. Scope limits what a token may do.", "OAuth 2.1 consolidates 2.0 and its best practices; PKCE is RFC 7636 (2015).", "E5's five-step authorization flow (Figure 06).", "https://modelcontextprotocol.io (authorization)", aliases=("OAuth", "PKCE", "scope", "PAT"), ch=(14,))
g("A2A", "protocol", "Agent-to-Agent protocol: an agent publishes an Agent Card (identity, skills, endpoints, auth requirements); a client agent sends a Task that moves through states (submitted, working, input-required, completed) and returns Artifacts. For delegating work to somebody else's agent, as opposed to MCP for giving your agent tools.", "Google, April 2025; donated to the Linux Foundation in June 2025; v0.3 (mid-2025) added signed Agent Cards and gRPC; v1.0 in March 2026; joined the Agentic AI Foundation in August 2026.", "E5 sets A2A against MCP; E9 uses its delegation model.", "https://a2a-protocol.org", aliases=("Agent Card", "Agent-to-Agent", "A2A v1.0"), ch=(14, 18))
g("AP2", "protocol", "Agent Payments Protocol: Google's September 2025 extension for agent-initiated payments, built on signed 'mandates' that record what the human authorized an agent to buy.", "", "E9's example of a contract a marketplace of agents would need.", "https://ap2-protocol.org", aliases=("mandates",), ch=(18,))
g("OWASP", "protocol", "The Open Worldwide Application Security Project: the OWASP Top 10 for LLM Applications (2025 list, codes LLM01–LLM10: prompt injection, improper output handling, excessive agency, unbounded consumption, and the rest) and the Agentic Top 10 (December 2025, codes ASI01–ASI10) are the threat vocabulary of E5, E7, and E11; the decks cite them by code.", "", "", "https://genai.owasp.org", aliases=("OWASP Top 10", "Agentic Top 10", "ASI01", "ASI06", "ASI08", "LLM01", "prompt injection", "tool poisoning", "Injection", "injection"), ch=(14, 20))
g("OpenAPI", "protocol", "The standard description format for HTTP APIs (formerly Swagger). Several 2023 tool systems derived tool schemas from OpenAPI documents; MCP replaced that with its own tool listing.", "", "", "https://www.openapis.org", aliases=("REST", "HTTP"))

# ---------------- systems, frameworks, and companies ----------------
g("FIPA", "system", "The Foundation for Intelligent Physical Agents: a 1996 consortium that standardized multi-agent systems, including an agent communication language in which every message carries a performative (inform, request, propose, refuse). Its interaction protocols include the contract net. Became an IEEE Computer Society standards committee in 2005; the specifications are now hosted by the IEEE and in archived copies rather than at fipa.org.", "1996; IEEE from 2005.", "E8's baseline: message type as claim type, thirty years before the chat transcript.", "https://www.fipa.org", aliases=("performative", "performatives", "FIPA-ACL"), ch=(4,))
g("Contract net", "system", "Reid Smith's 1980 protocol for distributing tasks among agents: a manager announces a task, contractors bid, the manager awards it, the contractor reports a result or failure. The first plan-do-check with typed messages.", "Smith, 'The Contract Net Protocol' (IEEE Transactions on Computers, 1980).", "The first row of E8's 'under every name' table.", "Smith (1980)", aliases=("Contract net (Smith; FIPA)", "contract net"), ch=(4,))
g("BDI", "system", "Belief–Desire–Intention agents: an architecture in which an agent holds beliefs about the world, desires (goals), and intentions (committed plans), and reconsiders intentions when beliefs change. Bratman's philosophy (1987) became an agent architecture in Rao and Georgeff's work.", "Rao & Georgeff, 'BDI Agents: From Theory to Practice' (ICMAS-95).", "What LLM agents carried forward (goal decomposition, halt as 'intention achieved or dropped') and what they dropped (an inspectable belief state).", "Rao & Georgeff (1995)", aliases=("Belief–Desire–Intention", "BDI agents"), ch=(4,))
g("PEAS", "system", "Performance measure, Environment, Actuators, Sensors: Russell and Norvig's frame for specifying an agent's task before designing it.", "Russell & Norvig, Artificial Intelligence: A Modern Approach.", "Chapter 2 starts from PEAS and ends at the nine components.", "Russell & Norvig, AIMA", aliases=("Russell", "Norvig", "AIMA"), ch=(2,))
g("ReAct", "system", "Reasoning and Acting: a prompting pattern in which the model alternates a thought, an action (a tool call), and an observation (the tool's result) until it answers. The first widely copied form of the agent loop.", "Yao et al., 'ReAct: Synergizing Reasoning and Acting in Language Models' (2022; ICLR 2023).", "E1's loop is ReAct with a halt condition and a ledger.", "https://arxiv.org/abs/2210.03629", aliases=("Yao",), ch=(5,))
g("Chain-of-thought", "system", "Prompting a model to write intermediate reasoning steps before its answer, which improves multi-step accuracy on large models. Tree of Thoughts (2023) generalizes the single chain to a searched tree.", "Wei et al. (2022); Yao et al., 'Tree of Thoughts' (2023).", "The step from prompting to programs in E1.", "https://arxiv.org/abs/2201.11903", aliases=("CoT", "Tree of Thoughts", "ToT", "chain-of-thought"), ch=(5,))
g("Toolformer", "system", "A 2023 Meta paper in which a model teaches itself when to call tools (calculator, search, calendar) by inserting API calls into text and keeping the ones that reduce loss.", "Schick et al. (2023).", "One of the 2023 'tools' systems in Chapter 6.", "https://arxiv.org/abs/2302.04761", ch=(6,))
g("Reflexion", "system", "An agent that keeps verbal self-reflections on failed attempts in an episodic memory and reads them on the next attempt. Memory as a claim about what went wrong.", "Shinn et al. (2023).", "E7's survey of memory designs.", "https://arxiv.org/abs/2303.11366", ch=(6, 16))
g("Generative Agents", "system", "The 2023 Stanford 'Smallville' paper: twenty-five agents in a simulated town with a memory stream, retrieval scored by recency, importance, and relevance, and periodic reflection. The reference design for retrieval-scored memory.", "Park et al. (2023).", "Figure 08's chunk, represent, store, score, inject is this paper's pipeline.", "https://arxiv.org/abs/2304.03442", aliases=("Smallville", "Park"), ch=(6, 16))
g("MemGPT / Letta", "system", "MemGPT (2023) treats the context window like RAM and an external store like disk, with the model paging memory in and out through tools. Letta is the company and framework that grew out of it.", "Packer et al. (2023).", "E7's survey: memory management as an operating-system problem.", "https://arxiv.org/abs/2310.08560", aliases=("MemGPT", "Letta"), ch=(16,))
g("RAG", "system", "Retrieval-Augmented Generation: retrieve documents relevant to the query, put them in the prompt, generate. The 2020 paper named the pattern; every memory layer in the course is a RAG loop over its own records.", "Lewis et al. (2020).", "", "https://arxiv.org/abs/2005.11401", aliases=("Retrieval-Augmented Generation", "embedding", "embeddings", "embeddinggemma"), ch=(16,))
g("AutoGPT", "system", "The March 2023 open-source project that ran GPT-4 in a loop with a goal, tools, and a file-based memory, and went viral. Autonomy without a halt condition: it looped, spent, and rarely finished.", "Toran Bruce Richards, 2023.", "E1's example of the loop without a halt.", "https://github.com/Significant-Gravitas/AutoGPT", ch=(6,))
g("BabyAGI", "system", "Yohei Nakajima's March 2023 task-management loop: create tasks, prioritize, execute, repeat. A few hundred lines that defined the 'autonomous agent' shape of 2023.", "", "", "https://github.com/yoheinakajima/babyagi", ch=(6,))
g("CAMEL", "system", "Communicative Agents for 'Mind' Exploration: two role-playing models (an AI user and an AI assistant) solve a task by chatting, with inception prompts fixing their roles. No checker; the assistant ends the task by emitting a token.", "Li et al. (NeurIPS 2023).", "E8's example of roles by prompt alone.", "https://arxiv.org/abs/2303.17760", ch=(6, 17))
g("MetaGPT", "system", "A multi-agent framework in which roles (product manager, architect, engineer, QA) pass structured documents (PRD, design, code) to one another, with executable feedback from running the code. Roles connected by documents rather than chat.", "Hong et al. (2023; ICLR 2024).", "E8's step from CAMEL: documents between roles.", "https://arxiv.org/abs/2308.00352", ch=(6, 17))
g("AutoGen", "system", "Microsoft's multi-agent conversation framework: an assistant agent and a user-proxy agent that runs code, conversing until someone says TERMINATE. Roles as configuration.", "Wu et al. (2023).", "", "https://arxiv.org/abs/2308.08155", ch=(6, 17))
g("CrewAI", "system", "A Python framework in which agents are defined by role, goal, and backstory and organized into crews with sequential or hierarchical process; a manager agent reviews in the hierarchical mode, and a task guardrail can return (bool, value).", "João Moura, 2023–24.", "", "https://docs.crewai.com", ch=(17,))
g("LangChain", "system", "The 2022 library that packaged chains, tools, agents, and memory for LLM applications. LangGraph (2024) is its state-graph runtime: nodes, edges, conditional routing, a checkpointer, and interrupt() for a human in the loop. LangSmith is the tracing and evaluation service.", "Harrison Chase, October 2022; LangGraph 2024.", "E2: every framework is a theory of who owns the loop. E8: the supervisor pattern as a state graph with a human interrupt.", "https://www.langchain.com", aliases=("LangGraph", "LangSmith", "supervisor", "StateGraph", "interrupt()", "checkpointer"), ch=(11, 17))
g("Pydantic AI", "system", "A Python agent framework from the Pydantic team: typed tool definitions, structured outputs validated by Pydantic models, and dependency injection. Used in the course's airline-operations testbed.", "2024 onward.", "", "https://pydantic.dev/docs/ai/overview/", ch=(11,))
g("Ollama", "system", "A local model runner: pulls open-weight models and serves them over an HTTP API on your machine, including an embeddings endpoint. Route B's substrate; E3 and E7 require a local model on both routes.", "", "", "https://ollama.com", aliases=("local model", "open-weight"))
g("Langfuse", "system", "An open-source observability platform for LLM applications: traces, spans, costs, and evaluation runs. E11's examples of 'receipts over narrative' use trace waterfalls of this kind (Figure 12).", "", "", "https://langfuse.com", aliases=("trace", "traces", "span", "spans"), ch=(20,))
g("Anthropic", "org", "The company that makes Claude, Claude Code, and MCP, and whose engineering posts the course reads: 'Building Effective Agents' (December 2024), 'How we built our multi-agent research system' (June 2025), 'Effective context engineering for AI agents' (September 2025), 'Effective harnesses for long-running agents' (November 2025), the Agent Skills post (October 2025), and 'Demystifying evals for AI agents' (January 2026), whose vocabulary (task, trial, grader, transcript, outcome) E10 uses.", "", "", "https://www.anthropic.com/engineering", aliases=("Building Effective Agents", "multi-agent research system", "Claude"))
g("OpenAI", "org", "Maker of GPT models, ChatGPT, function calling (June 2023), the Agents SDK, and Codex. 'A Practical Guide to Building Agents' (2025) is on the reading list.", "", "", "https://openai.com", aliases=("GPT-4", "ChatGPT", "o-series"))
g("Cognition", "org", "The company behind Devin. Walden Yan's June 2025 post 'Don't Build Multi-Agents' argues that split workers make conflicting implicit decisions unless they share full traces: the published counter-argument to Anthropic's multi-agent research post the same week.", "", "E8 weighs the two posts against each other.", "https://cognition.com/blog/dont-build-multi-agents", aliases=("Yan", "Devin"), ch=(17,))
g("Invariant Labs", "org", "The security group whose April 2025 'tool poisoning' demonstration hid instructions inside an MCP tool description, which the model followed. The E5 lab reproduces it with a harmless canary.", "", "", "https://invariantlabs.ai", aliases=("canary",), ch=(14,))
g("Linux Foundation", "org", "Home of the Agentic AI Foundation, formed in December 2025 with MCP, goose, and AGENTS.md as founding projects. A2A was donated to the Linux Foundation in June 2025 and joined the Agentic AI Foundation in August 2026, so neither protocol is governed by one vendor.", "", "", "https://www.linuxfoundation.org", aliases=("Agentic AI Foundation",))

# ---------------- benchmarks and evaluation ----------------
g("SWE-bench", "bench", "A benchmark of 2,294 real GitHub issues from twelve Python repositories; an agent must produce a patch that passes the repository's tests. SWE-bench Verified (2024) is a human-validated 500-task subset, now saturated at the frontier; SWE-bench Pro (2025) is the harder successor. SWE-agent (2024) built the first strong agent-computer interface for it; Agentless (2024) showed a non-agent pipeline competing with it.", "Jimenez et al. (2023); Yang et al. (2024); Xia et al. (2024).", "E10: what five agent benchmarks measure and what they hide.", "https://www.swebench.com", aliases=("SWE-agent", "Agentless", "SWE-bench Verified", "SWE-bench Pro"), ch=(7, 19))
g("HumanEval", "bench", "OpenAI's 2021 set of 164 hand-written Python programming problems with unit tests; pass@k is the metric. The first standard code benchmark, and now largely saturated.", "Chen et al. (2021).", "", "https://arxiv.org/abs/2107.03374", aliases=("pass@k",), ch=(19,))
g("GAIA", "bench", "A benchmark of real-world assistant questions that need browsing, tool use, and multi-step reasoning, with unambiguous answers; easy for humans, hard for agents.", "Mialon et al. (2023).", "", "https://arxiv.org/abs/2311.12983", ch=(19,))
g("WebArena", "bench", "A benchmark of tasks on self-hosted realistic websites (shopping, forums, code hosting) for web agents.", "Zhou et al. (2023).", "", "https://webarena.dev", ch=(19,))
g("ToolBench", "bench", "The dataset from ToolLLM ('Facilitating LLMs to Master 16000+ Real-world APIs', 2023): a benchmark for tool use over thousands of real APIs. Gorilla (2023) is the related Berkeley work on models that call APIs correctly.", "Qin et al. (2023); Patil et al. (2023).", "", "https://arxiv.org/abs/2307.16789", aliases=("Gorilla",), ch=(19,))
g("MT-Bench and Chatbot Arena", "bench", "LMSYS's 2023 evaluation work: MT-Bench (multi-turn questions graded by a strong model) and Chatbot Arena (crowd-sourced pairwise preference). The paper that named LLM-as-a-judge and measured its biases: position, verbosity, and self-enhancement.", "Zheng et al., 'Judging LLM-as-a-Judge with MT-Bench and Chatbot Arena' (NeurIPS 2023).", "E10's judge-bias table starts here.", "https://arxiv.org/abs/2306.05685", aliases=("MT-Bench", "Chatbot Arena", "Zheng", "LLM-as-a-judge", "judge", "Judge"), ch=(19,))
g("Judge biases", "bench", "What a model grading another model gets wrong: position bias (Wang et al. 2023, 'Large Language Models are not Fair Evaluators'), verbosity, self-preference (Panickssery, Bowman & Feng 2024 showed models recognize their own outputs; Wataoka et al. 2024 argue the mechanism is familiarity), and injection (hidden text in an answer moves the score).", "", "E10: a judge is admissible only if it is from another model family and survives an injection.", "Wang et al. (2023) arXiv:2305.17926; Panickssery, Bowman & Feng (2024) https://arxiv.org/abs/2404.13076; Wataoka et al. (2024) arXiv:2410.21819", aliases=("Panickssery", "Wataoka", "self-preference", "position bias", "verbosity bias"), ch=(19,))
g("BLEU", "bench", "The 2002 machine-translation metric: n-gram overlap between a candidate and reference translations. The 2017 Transformer paper reports its results in BLEU; the mini lecture reads those tables.", "Papineni et al. (2002).", "", "https://aclanthology.org/P02-1040/", ch=())
g("MAST", "paper", "The Multi-Agent System Failure Taxonomy from 'Why Do Multi-Agent LLM Systems Fail?': fourteen failure modes in three categories (specification and system design, inter-agent misalignment, task verification and termination), with prevalence figures from annotated traces.", "Cemri et al. (2025).", "E9's taxonomy; Figure 10's failure matrix.", "https://arxiv.org/abs/2503.13657", aliases=("Cemri", "Why Do Multi-Agent LLM Systems Fail"), ch=(18,))
g("Berkeley benchmark exploits", "paper", "A 2026 study in which the Berkeley RDI group broke agent benchmarks: each exploit is a grader that trusted something the agent could touch (the answer file, the judge's prompt, the test harness). The blog post (April 2026) broke eight; the paper, 'Do Androids Dream of Breaking the Game? Systematically Auditing AI Agent Benchmarks with BenchJack' (May 2026), audits ten and reports 219 flaws. The lesson for your own evals: check that the agent cannot reach the answers.", "Wang, Mang, Cheung, Sen & Song, Berkeley RDI blog, April 2026; Wang, Mang, Cheung, Li, Sen & Song, arXiv:2605.12673, May 2026.", "", "https://arxiv.org/abs/2605.12673", aliases=("Berkeley RDI", "BenchJack"), ch=(19,))
g("Transformer", "paper", "The 2017 architecture from 'Attention Is All You Need': scaled dot-product attention over queries, keys, and values (softmax of QK^T/sqrt(d) times V) instead of recurrence; multi-head attention; encoder and decoder stacks with residual connections and layer normalization; sinusoidal positional encodings; trained with Adam, dropout, and label smoothing; results reported in BLEU on the WMT newstest sets. Every model the course's harnesses call descends from it; GPT (Radford et al., 2018) kept the decoder only. The mini lecture reads the paper as a design document.", "Vaswani et al. (2017).", "", "https://arxiv.org/abs/1706.03762", aliases=("Attention Is All You Need", "Vaswani", "attention", "softmax", "multi-head attention", "decoder-only"), ch=(1,))
g("Degani and Wiener", "paper", "'Philosophy, policies, procedures and practices: the four P's of flight-deck operations': a procedure is only as good as the practice it produces, and the gap between them is where accidents live. The course's 'presence is not procedure' comes from here.", "Asaf Degani and Earl Wiener, chapter in Johnston, McDonald & Fuller (eds.), Aviation Psychology in Practice (Avebury, 1994; Routledge reissue 1997); the same framework is in NASA CR-177642, 'On the design of flight-deck procedures' (1994). Their 1997 IEEE paper, 'Procedures in complex systems: the airline cockpit,' is a separate work.", "", "https://ntrs.nasa.gov/citations/19940029437", ch=(3,))
g("Nygard, Release It!", "paper", "Michael Nygard's book on production software: stability patterns (circuit breaker, bulkhead, timeouts), capacity, and operations. Nygard also wrote the ADR template the course uses.", "Release It! 2nd edition (2018).", "E12's circuit-breaker simulator and the rollback doctrine.", "Reading list, Appendix E", aliases=("Nygard", "circuit breaker"), ch=(21,))

# ---------------- methods and general terms ----------------
g("TDD / BDD", "method", "Test-Driven Development: write the failing test first, then the code. Behavior-Driven Development: acceptance criteria written as behaviors (given, when, then) that a suite checks. Gates 2 and 4 of the five gates.", "", "", "Course Topic Guide, Chapter 3", aliases=("TDD", "BDD", "pytest", "uv run pytest"), ch=(3, 19))
g("Golden set", "method", "A fixed set of inputs with known-good outputs that an evaluation runs against every change; the regression delta is the difference between the baseline run and the candidate run. A gate turns red on a delta you pre-registered.", "", "E10's build (Figure 11): one run is an anecdote.", "Course Topic Guide, Chapter 19", aliases=("golden.jsonl", "regression delta", "delta gate", "baseline"), ch=(19,))
g("Red team", "method", "Probing your own system the way an adversary would, with the nine failure modes as the probe list, and recording what it did. E11's lab plants falsehoods and injections and reads the traces.", "", "", "Course Topic Guide, Chapter 20", aliases=("red-team", "Red Team", "adversary", "second-family adversary"), ch=(20,))
g("Lock with a TTL", "method", "A mutual-exclusion token that expires: a worker holding a lock on a file or task must renew it or lose it, so a crashed worker cannot block forever. Time To Live is the expiry.", "", "E9's build for parallel workers.", "Course Topic Guide, Chapter 18", aliases=("TTL", "lock", "locks"), ch=(18,))
g("Rollback", "method", "Returning a deployed system to its previous release, with the rollback itself recorded in the ledger. E12's claim is that the way back works before the way forward is used.", "", "", "Course Topic Guide, Chapter 21", aliases=("rollback", "code freeze", "Release"), ch=(21,))
g("JSONL", "method", "JSON Lines: one JSON object per line, append-only friendly. The ledger, memory.jsonl, and golden.jsonl use it.", "", "", "https://jsonlines.org", aliases=("jsonl",))
g("SHA-256", "method", "A cryptographic hash: a fixed-length fingerprint of a file or string that changes if any byte changes. Receipts carry one; the golden set is pinned by one; Figure 06's hash-pin check guards a tool description with one.", "", "", "", aliases=("sha256", "hash", "hash-pin"))
g("Workflow versus agent", "method", "Anthropic's 2024 distinction: a workflow is a predefined sequence of model calls and tools; an agent decides its own steps in a loop. Five workflow patterns (prompt chaining, routing, parallelization, orchestrator-workers, evaluator-optimizer) and then the agent.", "Anthropic, 'Building Effective Agents' (December 2024).", "E2 and Figure 03: who owns the loop.", "https://www.anthropic.com/engineering/building-effective-agents", aliases=("workflow", "workflows", "five patterns", "orchestrator-workers", "evaluator-optimizer"), ch=(11,))
g("Agentic AI", "method", "The stage in the course's five-stage progression (foundation, creation, core systems, action, full automation) where a model perceives, reasons, plans, and acts on an environment through tools in a loop with a halt condition. An agent, in this book, is one whose reasoner is a language model and whose loop halts.", "", "E0's two maps: the seven-layer stack and the five-stage progression.", "Course Topic Guide, Chapters 1 and 2", aliases=("agent", "Agent", "agents", "halt", "halt condition", "Halt", "loop", "the loop", "agent loop"), ch=(1, 2))
g("LLM", "method", "Large language model: a transformer trained on text to predict the next token, used through a chat or completion API. The inner ring of Figure 17: one window in, one answer out, nothing kept between calls.", "", "", "", aliases=("language model", "model", "token", "tokens"))
g("SDK / API / CLI", "method", "Software Development Kit: a library for building on a service (the Claude Agent SDK, the OpenAI Agents SDK, the MCP Python SDK). API: the HTTP interface itself. CLI: a command-line program. The course treats an SDK as the harness's loop exposed to your code.", "", "", "", aliases=("SDK", "SDKs", "API", "CLI"))

# ---------------- additions from the Oct 22 lecture-gap audit ----------------
g("OpenCode models: Big Pickle, Zen, Go", "harness", "The three ways a model reaches OpenCode in this course. Big Pickle is OpenCode's free model on the Zen gateway: an undisclosed model family with an unpublished context window, offered at no charge, with the caveat that free-period data may be used for training. OpenCode Zen is the gateway's set of named-family models. OpenCode Go is the paid tier ($10 a month as of fall 2026) with dollar limits per five hours, per week, and per month. Route B students use Ollama instead.", "", "Every exercise names the model; the cost tables in E6 and E9 are computed against these tiers.", "https://opencode.ai/docs/zen/; https://opencode.ai/docs/go/", aliases=("Big Pickle", "opencode/big-pickle", "OpenCode Zen", "OpenCode Go", "Zen gateway"))
g("System card", "paper", "A lab's published evaluation report for one model release: what was tested and how, residual failure rates, the safety level it ships under, and the behaviors seen in red-teaming. Anthropic, OpenAI, and Google DeepMind each publish them; E11 reads two as Design Analyses.", "", "Appendix C's nine failure modes are sourced to frontier system cards.", "https://www.anthropic.com/system-cards; https://openai.com/safety/", aliases=("system cards", "frontier system cards", "ASL-3"), ch=(20,))
g("Guardrail", "course", "A mechanism at an enforcement locus that refuses an action regardless of what the model decides: a permission deny, a server-side scope check, a hook, a commit-time diff check. A sentence in a prompt is a request, not a guardrail. E11's attack cards each name the guardrail under test.", "", "The course's test of any safety claim is where the check runs and whether it can say no.", "Course Topic Guide, Chapter 20", aliases=("guardrails",), ch=(12, 20))
g("Enforcement locus", "course", "The place in the pipeline where a check actually runs and can refuse: at the call (a schema or a hook), at the effect (a commit-time diff, git diff --cached), or at the door (release). gzkit moved its write fences from the call to the commit locus after the August 2026 hook incident, when a hook never saw the write it was guarding.", "", "", "Course Topic Guide, Chapters 12 and 20; Appendix G", aliases=("commit locus", "enforcement loci"), ch=(12, 20))
g("Incident casebook (Appendix G)", "course", "gzkit's dated record of its own failures, January to August 2026: the first repudiated attestation (June 13), four briefs attested Completed for code that did not exist (June 16), the ten-deep subagent chain whose summaries became facts (May 24), the stale-clone handoff (April 26), the hook that never saw the write (August 21–23), the marker-file gate (August 21). Every 'reference design' slide draws on it.", "", "The course's claim that these failures are ordinary rests on having the receipts for them.", "Course Topic Guide, Appendix G", aliases=("Appendix G", "casebook", "incident casebook"), ch=(9,))
g("Marker-file gate (presence is not procedure)", "course", "The August 21, 2026 gzkit incident: a pipeline gate checked only that a marker file was present, and a stale marker licensed about 350 lines of change with no dispatch and no review. The rule it produced: a presence check says 'armed', never 'ran'; the gate must read the record of the run.", "", "", "Course Topic Guide, Appendix G", aliases=("presence is not procedure", "marker file", "undispatched Stage 2"), ch=(9, 19))
g("Trust doctrine (T0–T3)", "course", "gzkit's assignment of a trust tier to every kind of input: T0 the operator's own words, T1 repository canon, T2 tool and command output, T3 anything a model wrote or fetched. Trust-chain poisoning is the failure where each layer accepts the layer below as fact, so no single step is wrong and the top is; gzkit's April 18, 2026 outage is the casebook example.", "", "", "https://gzkit.org/governance/trust-doctrine/", aliases=("trust doctrine", "trust-chain poisoning", "trust tier"), ch=(20,))
g("MX mode", "course", "gzkit's maintenance posture after the June 2026 audit (ADR-0.0.74): 'loose in the bay, hard at the door.' Work in progress may be untidy; every gate holds at the release door. The MX hangar is the branch where that work happens.", "", "", "Course Topic Guide, Chapter 21; Appendix G", aliases=("MX hangar", "loose in the bay"), ch=(21,))
g("DO IT RIGHT rules", "course", "The rule set gzkit adopted after the May 24, 2026 ten-deep chain: no summary is a fact until its source is read; every delegated result names what it read and ran; a subagent's report is T3 until a human or a test confirms it.", "", "Summary laundering is the failure; these are the rules that answer it.", "Course Topic Guide, Appendix G", aliases=("ten-deep chain",), ch=(18,))
g("Canary", "method", "Two uses in the course. In E5, a harmless payload planted in a tool description to show that the model follows hidden instructions (the Invariant Labs demonstration). From E11 on, a planted fake secret string searched for in images, logs, and commits to prove a leak path exists; E12's release gate greps for it.", "", "", "Course Topic Guide, Chapters 14, 20, 21", aliases=("canary string", "canary payload"), ch=(14, 20, 21))
g("Pre-registration", "method", "Writing the hypothesis, the measure, and the decision rule before collecting the data, so the result cannot be fitted to the outcome. The flight card is pre-registration applied to a build; HARKing (hypothesizing after results are known) is the failure it prevents.", "Nosek et al., 'The preregistration revolution' (PNAS, 2018); Kerr, 'HARKing' (1998).", "E10's gate is pre-registered: the delta that turns it red is named before the run.", "https://www.pnas.org/doi/10.1073/pnas.1708274114", aliases=("pre-registered", "HARKing", "Nosek", "Kerr"), ch=(19, 23))
g("Attack card", "course", "E11's pre-registered adversarial test: the objective (which is the falsifier), the failure-mode number it targets, the delivery path, the payload's SHA-256, the guardrail under test, and the expected observable. Two of the five are sealed and written by the Chase, so the builder cannot tune the system to them.", "", "", "Course Topic Guide, Chapter 20", aliases=("attack cards", "sealed card"), ch=(20,))
g("Two-stage review", "course", "Two reviewers with different questions in a fixed order, each unable to edit: the spec reviewer asks whether the change does what the brief asks inside the allowed paths; the quality reviewer, only after a spec PASS, asks whether it is done well. gzkit's four personas are implementer, spec reviewer, quality reviewer, and narrator. Order matters: a quality review of the wrong feature gives a confident PASS.", "", "", "E8 lecture, slide 8", aliases=("spec reviewer", "quality reviewer", "narrator", "spec review", "quality review"), ch=(17,))
g("Dispatch record", "course", "gzkit's one record per role per task: who was dispatched, with what brief, and what came back. No record means the role did not run, whatever the summary says: 'credit is never inferred.' A run with one agent declares itself with --single-driver --reason.", "gzkit ADR-0.18.0", "", "https://gzkit.org/user/concepts/subagent-pipeline/", aliases=("dispatch records", "credit is never inferred", "single-driver"), ch=(17,))
g("Deployment vocabulary", "method", "E12's terms. FastAPI: the Python web framework the reference service runs on. Wheel: Python's built binary package format. Docker and Podman: container runtimes; an image digest is the SHA-256 that names an exact image, as opposed to a tag that can move. Idempotency key: a client-supplied id so a retried request is applied once. Runbook: the written procedure an operator follows for a release or an incident.", "", "", "Course Topic Guide, Chapter 21", aliases=("FastAPI", "wheel", "Docker", "Podman", "image digest", "idempotency key", "runbook"), ch=(21,))
g("Stability patterns (Nygard)", "paper", "From Release It!: Timeouts (never wait forever), Circuit Breaker (stop calling a failing dependency and let it recover), Steady State (a system must run indefinitely without human intervention), Fail Fast (reject early rather than consume resources), Governor (slow down automated actions so a human can intervene), Force Multiplier (the pattern's dark side: automation that amplifies a mistake across the fleet). E12 applies Governor and Force Multiplier to agents.", "Nygard, Release It! 2nd ed. (2018).", "", "https://pragprog.com/titles/mnee2/release-it-second-edition/", aliases=("Timeouts", "Steady State", "Fail Fast", "Governor", "Force Multiplier"), ch=(21,))
g("Toolkit: uv, ruff, ty", "harness", "The course's Python toolkit. uv: the package and environment manager every command runs through (uv run, uv python install 3.14). ruff: the linter and formatter. ty: the type checker from the same team. VS Code is the assumed editor; the GitHub Student Developer Pack supplies the subscriptions Route A uses.", "Astral (uv, ruff, ty).", "", "https://docs.astral.sh/uv/", aliases=("uv", "ruff", "ty", "Student Developer Pack"))
g("Google ADK", "system", "Google's Agent Development Kit (2025): a Python and Java framework with workflow agents (sequential, parallel, loop) and LLM agents, built A2A-native and used for the comparison tables in E0 and E2.", "", "", "https://google.github.io/adk-docs/", aliases=("Agent Development Kit", "ADK"), ch=(11,))
g("Spec-driven kits: spec-kit, OpenSpec, BMAD, GSD", "system", "Kits that put a written specification ahead of agent-generated code: GitHub's spec-kit (2025), OpenSpec, BMAD (Breakthrough Method of Agile AI-Driven Development), and GSD. gzkit shares lineage with spec-kit and adds the ledger, gates, and attestation that the others leave to the human.", "", "The orientation's comparison table; Chapter 8's 'spec-driven kits' section.", "https://github.com/github/spec-kit; https://gzkit.org/examples/comparison-gzkit-speckit-bmad/", aliases=("spec-kit", "OpenSpec", "BMAD", "GSD"), ch=(8,))
g("Computer use", "harness", "Anthropic's October 2024 capability in which the screen is the tool: perception is a screenshot, and every action (click, type, scroll) is write-class. E3 uses it as the limiting case of a tool contract: the schema is 'any pixel'.", "", "", "https://www.anthropic.com/news/3-5-models-and-computer-use", aliases=("computer-use",), ch=(7, 12))
g("MAST categories FC1–FC3", "paper", "The three failure categories in Cemri et al.'s taxonomy: FC1 specification and system design (the task, role, or stopping condition was wrong), FC2 inter-agent misalignment (agents talked past each other), FC3 task verification and termination (nobody checked, or checked wrong). The paper reports prevalence by category from annotated traces; summary laundering is FC2 and FC3 at once.", "Cemri et al. (2025), v3.", "", "https://arxiv.org/abs/2503.13657", aliases=("FC1", "FC2", "FC3"), ch=(18,))
g("AI_LOG.md and LEDGER.md", "course", "Two files every repository keeps. AI_LOG.md is the Sprint's attribution record: what was asked, which model, what was kept, what was rejected, why, and how it was verified. LEDGER.md (or ledger.jsonl) is the event log: sorties, verdicts, gates, commits. design-analyses/ holds the Design Analyses.", "", "The AI log is discussed in Drift; the ledger is what the Chase reads.", "Course Topic Guide, Chapters 22 and 23", aliases=("AI_LOG.md", "LEDGER.md", "AI log", "design-analyses/"), ch=(22, 23))
g("Course Topic Guide", "course", "The outline edition of the textbook, Answerable Systems: twenty-six chapters (Part I the posture, Part II the survey, Part III the build, Part IV the method) and appendices A–G. When a slide says 'chapter 16' or 'Appendix C', this is the book; the chapter-to-Evolution map on its front page says which chapters each week uses.", "", "", "/textbook/", aliases=("textbook", "the book"), ch=())
g("OpenTelemetry", "protocol", "The vendor-neutral standard for traces, metrics, and logs: a trace is a tree of spans, each with a start, an end, attributes, and a parent; OTLP is the wire protocol; the GenAI semantic conventions name the attributes for model calls and tool calls. Langfuse and LangSmith ingest it.", "CNCF, 2019 onward.", "E11's receipts are spans; Figure 12 is a span waterfall.", "https://opentelemetry.io", aliases=("OTel", "OTLP", "span tree", "GenAI conventions"), ch=(20,))
g("MCP threat mechanisms", "protocol", "E5's four: tool poisoning (instructions hidden in a tool description), the confused deputy (a server acts on the user's authority for someone else's request), rug pull (a tool description changes after approval), and cross-server shadowing (one server's description instructs the model about another server's tools). The defenses are hash-pinning descriptions (tool-pins.json), scoped tokens, and treating every description as untrusted content.", "Invariant Labs (April 2025) and the MCP security best-practices page.", "", "https://modelcontextprotocol.io/specification/draft/basic/security_best_practices", aliases=("confused deputy", "rug pull", "cross-server shadowing", "resource injection", "tool-pins.json"), ch=(14,))
g("Hollow test (hollow antibody)", "course", "A check that cannot fail: a test that compares the code with itself, an assertion with no input that could make it false, a gate that looks for a file rather than a result. gzkit's June 2026 audit found that its own hollow-test detector was hollow (ADR-0.0.73). A live negative control (remove the feature, watch the test go red) is the cure.", "", "E10's Sortie 10 and the RED witness.", "Course Topic Guide, Chapter 19", aliases=("hollow antibody", "hollow test", "tautological test", "live negative control", "@enforces"), ch=(19,))
g("τ-bench family", "bench", "τ-bench (Sierra, 2024) scores an agent on tool use with a simulated user in retail and airline domains, and introduced pass^k: the chance that k independent trials all succeed, which punishes inconsistency. τ²-bench (2025) adds a user who also acts on tools. AgentBench, CAR-bench, and FieldWorkArena are the other agent benchmarks E10 compares.", "Yao, Shinn, Razavi & Narasimhan (2024).", "E10's point: one run is an anecdote; pass^k makes consistency the score.", "https://arxiv.org/abs/2406.12045", aliases=("τ-bench", "tau-bench", "pass^k", "τ²-bench", "AgentBench"), ch=(19,))
g("Context rot and lost in the middle", "paper", "Two results about long windows. Liu et al. (2023), 'Lost in the Middle': models use information at the start and end of a long context better than the middle. Chroma's 2025 'Context Rot' report: performance degrades as input length grows even on simple tasks. Both support E6's budget rule and the four compaction moves (context editing, tool-result clearing, a keep list, re-seeding).", "", "", "https://arxiv.org/abs/2307.03172", aliases=("Context Rot", "Lost in the Middle", "context editing", "tool result clearing"), ch=(15,))
g("AI governance frameworks", "org", "The regulatory and standards landscape E0 situates the course against: the NIST AI Risk Management Framework (2023), the EU AI Act (2024, in force in stages), ISO/IEC 42001 (the AI management-system standard, 2023), and the third-party audit literature (Raji et al., 'Outsider Oversight', 2022; Groves et al., 'Auditing Work', 2024). The course's claim is that none of them reaches the engineer's desk; index zero does.", "", "", "https://www.nist.gov/itl/ai-risk-management-framework", aliases=("NIST AI RMF", "EU AI Act", "ISO/IEC 42001", "Raji", "Auditing Work"), ch=(3,))
g("Background and cloud agents", "harness", "Agents that run without a terminal open: Codex cloud (sandboxed tasks that open pull requests), GitHub Copilot's cloud agent, Claude Code's cloud sessions and GitHub Action, scheduled routines. E12's survey: the same loop, with the human further from index zero, so the release gates matter more.", "", "", "Course Topic Guide, Chapter 9", aliases=("background agents", "cloud agent", "Codex cloud agent", "Claude Code GitHub Action", "routines"), ch=(9, 21))
g("Memory retrieval vocabulary", "method", "E7's terms. Bag-of-words and TF-IDF: scoring by word overlap, auditable and blind to synonyms (recall.py's Path B). Embeddings and cosine similarity: a vector per text, scored by angle, handles paraphrase and is not auditable (Path A, via Ollama's /api/embed with embeddinggemma, nomic-embed-text, or qwen3-embedding). Supersedes: a record that names the one it replaces. Memory kinds: episodic (what happened), semantic (what is true), procedural (how to), working state (this session).", "", "", "Course Topic Guide, Chapter 16", aliases=("TF-IDF", "bag-of-words", "cosine", "supersedes", "episodic", "semantic memory", "procedural memory", "nomic-embed-text", "all-minilm"), ch=(16,))
g("Harness configuration knobs", "harness", "The per-harness settings E5 and E6 compare: Claude Code's /compact, /context, model_auto_compact_token_limit, CLAUDE.local.md; OpenCode's compaction settings and opencode export and stats; Cursor's .cursor/rules .mdc files with 'Apply Intelligently'; Gemini CLI's GEMINI.md and context.fileName. The lesson is that the control surface differs by harness, and the control-surface matrix records which rules each one enforces versus only requests.", "", "", "https://gzkit.org/governance/agents-md-doctrine/", aliases=("control-surface matrix", "/compact", "/context", "CLAUDE.local.md", "GEMINI.md", "agents-md doctrine"), ch=(14, 15))
g("Routing and model families", "method", "E9's cost-aware routing: RouteLLM and FrugalGPT (route cheap first, escalate on doubt); a route table with a budget; degraded mode when the preferred route is down. The open-weight families the decks name as adversaries from another family: GLM, DeepSeek, Kimi, Qwen, MiniMax, MiMo, Nemotron. A stealth model is one whose family is undisclosed (Big Pickle).", "", "", "Course Topic Guide, Chapter 18", aliases=("RouteLLM", "FrugalGPT", "degraded mode", "stealth model", "DeepSeek", "Qwen", "Kimi", "GLM", "Nemotron"), ch=(18,))
g("gz commands", "course", "The gzkit CLI verbs the decks cite: gz init, gz prd, gz adr (and gz adr evaluate --red-team), gz validate (with --distribution, --instructions-files-budget, --invariant-coherence), gz handoff, gz insights remember (the corpus of operator corrections), gz obpi dispatch / lock / repudiate / complete, gz covers, gz arb red, gz patch release, gz closeout --ceremony, gz status.", "", "", "https://gzkit.org/user/quickstart/", aliases=("gz validate", "gz handoff", "gz obpi", "gz closeout", "gz insights", "insights corpus"), ch=(25,))
g("ADR-1 apparatus", "course", "E2's tools for writing the first ADR: WWHTBT (what would have to be true), the pre-mortem (assume it failed; say why), constraint archaeology (where did each constraint come from), ten peer challenges, the decomposition scorecard, and the abstraction tax (what each layer costs on every call).", "", "", "Course Topic Guide, Chapter 11", aliases=("WWHTBT", "pre-mortem", "constraint archaeology", "abstraction tax", "decomposition scorecard"), ch=(11,))
g("gzkit founding documents", "course", "why.md (the Degradation Pattern, why the kit exists), charter (what the kit promises), lineage (where it came from), genesis (the origin transcript), command doctrine (how commands may act), the control-surface matrix, and the guides (guide-prd, guide-adr, guide-tasks, guide-releasing). The orientation lists them as readings; the textbook's Readings link each one.", "", "", "https://gzkit.org/user/reference/", aliases=("why.md", "genesis.md", "charter", "lineage", "command doctrine"), ch=(3,))
g("Sprint and Drift essays", "course", "The newsletter essays that open chapters: Tree Hollow, Who answers for the code, Enthusiasm Is All You Need, Get the Balance Right, Stop the presses, hail the autoloom, The cost of the wrong abstraction went to zero, Woven, Code ergo sum, Optimism's flames, Newtonian motion, Can you outrun the truth?, Turn and Face the Change. Each chapter's Readings links the one it opens with.", "sprintanddrift.substack.com (June–July 2026).", "", "https://sprintanddrift.substack.com", aliases=("Who answers for the code", "Newtonian motion", "Turn and Face the Change", "Code ergo sum", "Woven", "Optimism's flames"), ch=(22,))
g("JADE, Voyager, OpenHands, Aider, Jules, Zed", "system", "Names from the survey tables. JADE: the Java FIPA-compliant agent platform (2000s). Voyager (2023): a Minecraft agent that writes and stores skills as code. OpenHands (2024): an open-source coding-agent platform. Aider: a terminal pair-programming tool (2023). Jules: Google's asynchronous coding agent (2025). Zed: an editor with agent features.", "", "", "", aliases=("JADE", "Voyager", "OpenHands", "Aider", "Jules", "Zed"), ch=(7, 8))
